"""Render the four-step execution record without changing any financial input."""
from decimal import Decimal
from html import escape as h
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs/company-resolutions/execution-2026-11-04'


def read(name):
    return json.loads((OUT / name).read_text())


def b(value, precision=3):
    return 'Unavailable' if value is None else f'{Decimal(value)/Decimal(10**9):,.{precision}f}B'


def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>' + ''.join('<th>'+h(x)+'</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows) + '</tbody></table></div>'


def main():
    step1 = read('step-1-apple-operating.json'); funding = read('step-2-financing.json')
    own = read('step-3-alphabet-ownership.json'); platform = read('step-4-platform-separation.json')
    logs = read('run-log.json'); validation = read('validation.json')
    projection = json.loads((ROOT / 'docs/company-resolutions/implementation-2026-11-03/platform-cashflows.json').read_text())
    sections = []
    sections.append('<section><h2>What changed</h2><p>The four workstreams were executed in sequence. Apple has a new five-year numerical operating-income reconciliation; Apple and Meta have ten explicit financing workpapers and issuer evidence requests; Alphabet has a separate ownership/value bridge; the platform now exposes six distinct readiness checks.</p><p><strong>No missing historical amount was manufactured.</strong> No new verified historical FCFF or FCFE cell was established. The 18 available calculations already existed under their stated conventions; five Alphabet consolidated FCFE observations are now expressly recognized by the separate availability contract. Historical amounts, forecast policies and the original strict review are preserved.</p>' + table(['Measure','Current position'],[
        ['FCFF under stated historical cash conventions','13 available; Apple FY2024/25 unavailable'],
        ['FCFE under a complete stated consolidated convention','5 Alphabet observations available before minority allocation'],
        ['FCFE with incomplete financing classification','10 provisional Apple/Meta observations'],
        ['Exact parent-common FCFE','0 established across the three companies'],
        ['Original strict parent-common coverage review','17 failed cells remain: 2 FCFF + 15 parent-common FCFE'],
        ['Company / overall financial review','OPEN for all three companies']]) + '</section>')
    sections.append('<section><h2>Execution in order</h2>' + table(['Step','Work performed','Outcome','UTC record'],[
        [str(r['stage']), ['Apple operating-income reconciliation','Apple / Meta financing reconciliation','Alphabet ownership and value separation','Platform consumer separation'][r['stage']-1],h(r['outcome']),h(r['recorded_at_utc'])] for r in logs]) + '</section>')
    rows=[]
    for t in ('AAPL','META','GOOGL'):
        for p in projection['companies'][t]['periods']:
            rows.append([t,'FY'+str(p['fiscal_year']),b(p['fcff']['amount_usd']),
                'Missing interest' if p['fcff']['amount_usd'] is None else 'Available · stated convention',
                b(p['fcfe']['amount_usd']), 'Consolidated · before NCI' if t=='GOOGL' else 'Provisional · financing open','Unavailable',
                '<a href="'+h(p['fcfe']['source_urls'][0],quote=True)+'">Filing</a>'])
    sections.append('<section><h2>Five-year cash-flow inventory</h2><p>USD billions; rounded here to three decimals. Exact retained dollar values, fractions, source dates and statuses remain in the workpapers and platform export. “Available” describes the declared historical method, not forecast alignment or fair value per share.</p>' + table(['Company','FY','FCFF','FCFF status','FCFE review amount','FCFE status','Parent-common FCFE','Source'],rows) + '</section>')
    rows=[]
    for p in step1['periods']:
        rows.append(['FY'+str(p['fiscal_year']), b(p['filing_operands_usd']['ebit']),b(p['reported_cfo_less_cash_ppe']['amount_usd']),
            b(p['provision_minus_cash_tax']['amount_usd']),b(p['aggregate_after_tax_conversion_UNCLASSIFIED']['amount_usd']),
            b(p['broad_statement_movement_diagnostic_NOT_FCFF']['amount_usd']),b(p['tax_timing_diagnostic_NOT_FCFF']['amount_usd']),'0'])
    sections.append('<section><h2>1. Apple: operating income reconciled to cash</h2><p>The workpaper starts with source-bound EBIT, reported tax provision and pretax income, reported cash-statement D&amp;A, actual signed cash movements and cash PP&amp;E. It separately identifies SBC and net nonoperating income under the reported effective-tax allocation convention.</p><div class="formula">Cash FCF = tax-timing diagnostic + SBC + allocated after-tax net nonoperating income + (tax provision − cash taxes)</div><p>Each year ties exactly using rational arithmetic. The tax provision minus cash-tax conversion is observable, but subtracting it from an aggregate does not identify which mixed caption contains tax, noncurrent assets, capital creditors or nonoperating adjustments.</p>' + table(['FY','EBIT','CFO − cash PP&E','Provision − cash tax','Unclassified aggregate after conversion','Broad diagnostic*','Tax-timing diagnostic*','Bridge difference'],rows) + '<p class="note">*Neither diagnostic is certified FCFF or eligible for automatic forecast calibration. Their difference demonstrates the effect of unresolved classification; it is not a valuation range or an uncertainty bound.</p><p>FY2024 note depreciation plus intangible amortization is 11.800B versus cash-statement D&amp;A of 11.445B: a 0.355B population difference. FY2025 11.700B is compatible with 11.698B at the notes’ displayed precision, but compatibility alone does not certify complete expense alignment. No 0.355B plug, inferred amortization or book-balance cash flow is inserted. <a href="https://www.sec.gov/Archives/edgar/data/320193/000032019326000026/aapl-20260926.htm">Later comparative filing, Notes 5–6</a>.</p><p><strong>Remaining:</strong> A1 FY2024/25 gross interest for the existing method; A4 mixed operating/tax movements; A5 expense-aligned noncash population; A6 investment alignment for a replacement series. Cash PP&amp;E remains the explicit historical perimeter. A broader economic-investment series would require a separate matched schedule.</p><p><a href="step-1-apple-operating.json">Exact Apple reconciliation</a></p></section>')
    rows=[]
    for t,c in funding['companies'].items():
        for p in c['periods']:
            rows.append([t,'FY'+str(p['fiscal_year']),b(p['identified_net_borrowing_usd']),b(p['other_financing_net_usd']),b(p['provisional_fcfe_usd']),'Unclassified','0'])
    questions=''.join('<details><summary>'+t+' evidence request · draft, not sent</summary><ol>'+''.join('<li>'+h(q)+'</li>' for q in c['clarification_request']['questions'])+'</ol><p>Requested reply: year, transaction, cash amount, statement caption, gross/net basis, parent repayment containment and public source. Public or disclosable information only.</p></details>' for t,c in funding['companies'].items())
    sections.append('<section><h2>2. Apple and Meta: financing kept provisional</h2><p>All ten complete financing statements reconcile, and all ten provisional FCFE calculations reproduce CFO less the stated cash-investment perimeter plus identified net borrowing. Known equity, dividends, taxes on awards and buybacks stay outside net borrowing; known debt and lease principal are counted once.</p>' + table(['Company','FY','Identified net borrowing','Other financing, net','Provisional FCFE','Debt content of Other','Statement difference'],rows) + '<p><strong>A net Other amount is not a bound on missing debt cash.</strong> Offset receipts and repayments may be larger than the net. Apple’s actual finance-lease principal/containment remains unestablished; Meta’s separately identified finance-lease principal is already deducted once. None of the ten provisional figures is promoted to complete FCFE.</p><p>Meta’s incurred capitalized interest is not a direct cash add-back. The current expense-based FCFF stays available; a broader adjustment requires matched cash capitalization, investment and tax evidence. Existing source research covers original annuals, target quarterlies, public notes, correspondence and commentary; the evidence requests state precisely what remains absent.</p>'+questions+'<p><a href="step-2-financing.json">Annual financing workpapers and evidence requests</a></p></section>')
    rows=[]
    for p in own['periods']:
        rows.append(['FY'+str(p['fiscal_year']),b(p['consolidated_fcfe_usd']),b(p['book_nci_context_only_usd']),b(p['redeemable_nci_ALREADY_INCLUDED_usd']),'Unavailable','Unavailable','Counted once'])
    sections.append('<section><h2>3. Alphabet: consolidated history and parent value separated</h2><p>All five consolidated FCFE observations remain available before minority allocation. Parent-common cash attribution is a different output, and remains null. Historical cash attribution does not become known merely because a subsidiary valuation can be modeled.</p>' + table(['FY','Consolidated FCFE','Book NCI, context only','Redeemable NCI, included','NCI fair value','Parent-common FCFE','Lease cash'],rows) + '<p>For a consolidated FCFF valuation, use a supported, dated bridge from operating value through eligible nonoperating assets, debt, other claims and outside interests to parent equity. For an FCFE valuation, do not deduct debt a second time after its cash effects are captured in financing. Cash additions must match returns excluded from the forecast; outside claims must match the valued perimeter.</p><p>No NCI fair value or subsidiary ownership percentage is invented. Book NCI is not used as fair value, redeemable NCI is not added twice, and a 2026 financing round is not backdated to FY2021–25. The five bridge templates retain null values until supported.</p><p><a href="step-3-alphabet-ownership.json">Ownership records and parent-value bridge templates</a></p></section>')
    sections.append('<section><h2>4. Platform: six distinct checks</h2><p>The existing cash-flow endpoint now returns additive readiness information. The Cash flows view explains historical availability separately from the downstream checks below. It retains original amounts, clearance flags, ownership labels and the original failed review. Missing historical data does not disable the manual forecast route; that route validates its own inputs.</p>' + table(['Check','Treatment'],[
        ['Historical calculation','Available / provisional / missing under its specific method and ownership'],
        ['Exact parent cash attribution','Separate financing or minority-attribution check'],
        ['History-to-forecast comparability','No automatic calibration or cross-basis FCFF CAGR before a reviewed bridge'],
        ['Forward valuation','Own financing, tax, discount-rate and terminal validation'],
        ['Parent equity value','Dated cash / debt / claims / NCI bridge matching valuation perimeter'],
        ['Fair value per share','Supported equity numerator and dated share/class/award denominator']]) + '<p>A company-switch defect identified by the independent review was fixed: prior-company amounts are hidden immediately while the next company loads, even without remounting the component. A delayed-response regression test covers this path.</p><p>The previously started saved-discount-input helper was also validated in this run. It offers an explicit choice to reuse existing dated CAPM operands; it makes no market refresh, automatic adoption, beta change or borrowing assumption. It does not fill any missing historical amount.</p><p><a href="accepted-policy.json">Consumer-separation adoption record</a> · <a href="step-4-platform-separation.json">Runtime classification and unchanged-value checks</a></p></section>')
    tests=[['Apple exact source replay','5 CFO, 5 financing and 5 tax-note sums; 2 later D&A comparisons'],
        ['Meta / Alphabet source replay','10 financing statements; 0 source mismatches or estimated operands'],
        ['Python / API regression tests',str(validation['python_api_tests']['passed'])+' passed'],
        ['Frontend suite',str(validation['frontend_tests']['passed'])+' passed in '+str(validation['frontend_tests']['files'])+' files'],
        ['Frontend production build',validation['frontend_build']],
        ['Apple / Meta valuation parity','All six Base/Bear/Bull results unchanged'],
        ['Live browser / served API',str(validation['live_browser'])],
        ['Independent audit',str(validation['independent_review'])],
        ['Financial completion','OPEN; no new verified historical cells']]
    sections.append('<section><h2>Validation and run history</h2>'+table(['Check','Result'],tests)+'<p>Initial development startup selected the system’s incompatible Node 18; it was restarted with the already-installed Node 24 runtime. The default headless browser binary was unavailable, so visual/live checks used installed Google Chrome. No package, source value or valuation assumption changed to resolve these verification obstacles.</p><p>Source/statement checks, software checks and financial clearance are separate verdicts. Passing the first two does not erase the remaining evidence gaps. The old source projection retains its SHA256 pin and all 17 failed strict coverage cells.</p><p><a href="validation.json">Validation record</a> · <a href="run-log.json">Sequential run log</a> · <a href="independent-review/findings.md">Independent findings</a></p></section>')
    sections.append('<section><h2>Remaining decisions and evidence</h2>'+table(['Area','What is still required','What can already be used'],[
        ['Apple existing FCFF','Exact gross expensed interest for FY2024/25, or a separately approved fully reconciled five-year replacement','FY2021–23 FCFF under its stated cash convention'],
        ['Apple operating alternative','Mixed operating/tax components, D&A expense population and matched investment alignment','Five exact diagnostic bridges, with no adoption'],
        ['Apple / Meta full FCFE','Annual Other debt classification; Apple lease-principal containment','Ten provisional disclosed-component calculations'],
        ['Meta expanded unlevered basis','Matched paid capitalized interest, capex and tax treatment','Five current expense-based FCFF observations'],
        ['Alphabet parent cash / equity','Exact cash attribution for parent history; separate dated NCI valuation for parent value','Five consolidated FCFF and FCFE observations'],
        ['Forecast comparison and per share','SBC/tax/investment bridge, reviewed forward financing/rates and cash/claims/shares/classes/awards','Manual forecast route with independent input validation']])+'<p>No outgoing issuer communication was sent. The next external action, if chosen, is the prepared evidence request. A disclosed-component proxy or new valuation assumption would need its own explicit review; this run does not silently adopt one to force coverage.</p></section>')
    sections.append('<section><h2>Methodology and reproducibility</h2><p>Historical FCFF: CFO + gross expensed interest × (1 − reported provision / pretax income) − stated cash PP&amp;E. Historical FCFE: CFO − stated cash investment + identified net borrowing. Meta retains the previously approved identified disposal-receipt corrections. These are source-supported derived measures with declared conventions, not separately audited filing line items.</p><p>The <a href="https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/free-cash-flow-valuation">CFA formulation</a> supports both CFO and operating-income approaches; it does not supply missing issuer components. The <a href="https://pages.stern.nyu.edu/adamodar/New_Home_Page/littlebook/valuepershare.htm">consolidated valuation / minority-interest guidance</a> supports a matching outside-interest deduction, not book-value substitution.</p><p>Replay stages 1–4 with <a href="../../../scripts/reconcile_pilot_execution.py">the offline reconciliation script</a>; source pins are retained in <a href="baseline.json">the baseline</a>. Each stage records one ordered event. Original source bytes, adopted cash-flow projection and preload policy values are preserved. Current implementation details supplement earlier company logs rather than overwrite them.</p><p><a href="../commentary-research-2026-11-04/README.md">Prior 52-source commentary research</a> · <a href="../OPEN-ROADBLOCKS.md">Current roadblock register</a> · <a href="../implementation-2026-11-03/platform-cashflows.json">Preserved source projection</a></p></section>')
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src 'self' data:; base-uri 'none'; form-action 'none'"><title>Three-company cash-flow implementation — 4 November 2026</title><style>
    :root{--ink:#193b4e;--muted:#607281;--gold:#ac862b;--line:#dbe4ea;--bg:#f2f5f7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:42px 34px 80px}header{margin-bottom:28px}h1{font:48px/1.12 Georgia,serif;letter-spacing:-1.3px;margin:14px 0}h2{font:29px/1.25 Georgia,serif;margin:0 0 16px}p{max-width:1060px}.eyebrow{letter-spacing:.13em;text-transform:uppercase;font-size:12px;font-weight:700;color:var(--muted)}.status{border-left:4px solid var(--gold);padding:14px 20px;background:#faf5e9;margin:24px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metric{padding:22px;background:white;border:1px solid var(--line);border-radius:9px}.metric strong{display:block;font:37px Georgia,serif}.metric span{font-size:13px;color:var(--muted)}section{background:#fff;border:1px solid var(--line);border-radius:12px;padding:28px;margin-top:22px}.scroll{overflow-x:auto;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}th{text-align:left;background:#f1f5f8;color:var(--muted);font-weight:650}td,th{padding:12px 13px;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{font-weight:600}a{color:#295d78;text-underline-offset:3px}.note{color:var(--muted);font-size:13px}.formula{padding:18px;background:#f1f5f8;font:15px/1.7 ui-monospace,monospace}details{padding:16px;background:#f6f8fa;margin:12px 0;border-radius:7px}summary{cursor:pointer;font-weight:600}li{margin:10px 0}@media(max-width:700px){main{padding:24px 14px}h1{font-size:34px}.metrics{grid-template-columns:1fr 1fr}section{padding:20px 16px}table{min-width:620px}}@media print{body{background:white}main{padding:0}section{break-inside:avoid;border-radius:0}.scroll{overflow:visible}a{color:inherit}}
    </style></head><body><main><header><div class="eyebrow">Valuation Platform · AAPL / META / GOOGL · FY2021–FY2025</div><h1>Four-step implementation run</h1><p>4 November 2026 · Source reconciliation, financing review, ownership separation and platform integration</p><div class="status"><strong>The four workstreams have been executed. Financial clearance remains OPEN.</strong><br>Available calculations remain usable within their stated scope; unresolved financing, operating-input and ownership components remain explicit.</div><div class="metrics"><div class="metric"><strong>18</strong><span>Available under stated conventions</span></div><div class="metric"><strong>10</strong><span>Provisional financing calculations</span></div><div class="metric"><strong>2</strong><span>Missing required FCFF inputs</span></div><div class="metric"><strong>0</strong><span>New verified historical cells</span></div></div></header>'''+''.join(sections)+'</main></body></html>'
    html=html.replace('independent-review/findings.md','independent-review/README.md')
    (OUT/'report.html').write_text(html)
    print('Rendered detailed implementation report.')


if __name__ == '__main__':
    main()
